vulnerable_code:
app.post('/api/users/messages/read', async (req, res) => {
  const { messageId } = req.body;
  await User.updateOne({ 'messages._id': messageId }, { $set: { 'messages.$.read': true } });
  res.send('Marked read');
});

corrected_code:
app.post('/api/users/messages/read', async (req, res) => {
  const { messageId } = req.body;
  await User.updateOne({ _id: req.user._id, 'messages._id': messageId }, { $set: { 'messages.$.read': true } });
  res.send('Marked read');
});
